import zipfile
from xml.etree import ElementTree as ET

def local(tag):
    return tag.rsplit('}', 1)[-1]

def find_child(elem, name):
    for e in elem:
        if local(e.tag) == name:
            return e
    return None

z = zipfile.ZipFile('budget.xlsx')
wb = ET.fromstring(z.read('xl/workbook.xml'))
rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
relmap = {r.get('Id'): r.get('Target') for r in rels}
rid = None
for k, v in find_child(wb, 'sheets')[0].attrib.items():
    if local(k) == 'id':
        rid = v
root = ET.fromstring(z.read(relmap[rid].lstrip('/')))

def cell(ref):
    for row in find_child(root, 'sheetData'):
        for c in row:
            if c.get('r') == ref:
                v = find_child(c, 'v')
                return float(v.text) if v is not None and find_child(c, 'f') is None else None
    return None

cats = {}
for r in range(11, 23):
    a = cell('A%d' % r); c = cell('C%d' % r)
    if c is not None:
        cats.setdefault(a, []).append(c)

total = 0
for cat, vals in cats.items():
    sub = sum(vals)
    total += sub
    print('%-15s %s = %.0f' % (cat, ', '.join(str(int(v)) for v in vals), sub))
print('TOTAL EXPENSES = %.0f' % total)
print('Check C23 formula =SUM(C11:C22) -> %d' % total)
"
